/* Ten Forty - settings plumbing
 *
 * The settings page is a real web page, served by GitHub Pages, and handed to
 * the phone as an https URL. It cannot be a data: URI: iOS refuses to load one
 * in the config webview, which leaves iPhone users with a dead settings button.
 *
 * The page itself is generated by scripts/config-page.js into docs/config.html
 * and committed; this file only opens it. The current settings travel in the
 * URL fragment so the page opens on the watch's real values.
 */

var CONFIG_URL = 'https://damosullivan.github.io/ten-forty/config.html';

/* Mirrors DEFAULT_OPTS in scripts/config-page.js. The watch always sends all
 * nine keys, so this only matters before it has said anything. If you add a
 * setting, change both. */
var DEFAULT_OPTS = { Theme: 0, Align: 0, DateAlign: 1, DateFormat: 0, DatePos: 2, OhWords: 1, Weight: 0, Case: 0, Transition: 2 };

function loadOpts() {
  try {
    var raw = localStorage.getItem('ten-forty');
    if (raw) {
      var o = JSON.parse(raw);
      var out = {};
      for (var k in DEFAULT_OPTS) {
        out[k] = (o[k] === undefined) ? DEFAULT_OPTS[k] : o[k];
      }
      return out;
    }
  } catch (e) { /* ignore */ }
  return JSON.parse(JSON.stringify(DEFAULT_OPTS));
}

function saveOpts(o) {
  try { localStorage.setItem('ten-forty', JSON.stringify(o)); } catch (e) {}
}

function sendOpts(o) {
  Pebble.sendAppMessage(o, function () {
    console.log('settings sent');
  }, function (e) {
    console.log('settings failed: ' + JSON.stringify(e));
  });
}

/* The watch is the source of truth. It pushes its settings on launch and we
 * mirror them here, so the config page always opens on the real values. The
 * phone must not push settings on startup: that used to overwrite whatever the
 * watch had, which made the face appear to change on its own. */
Pebble.addEventListener('appmessage', function (e) {
  var payload = e.payload || {};
  var opts = loadOpts();
  var changed = false;
  for (var k in opts) {
    if (payload[k] !== undefined && payload[k] !== opts[k]) {
      opts[k] = payload[k];
      changed = true;
    }
  }
  if (changed) saveOpts(opts);
});

/* A round display gives the date a narrow chord at the top, so the two wide
 * formats are withheld there rather than shown and truncated. Any failure
 * offers all of them and lets the watch clamp. */
function maxDateFormat() {
  try {
    var info = Pebble.getActiveWatchInfo();
    var p = (info && info.platform) || '';
    if (p === 'chalk' || p === 'gabbro') return 1;
  } catch (e) { /* not connected, or an app without the call */ }
  return 3;
}

Pebble.addEventListener('showConfiguration', function () {
  var opts = loadOpts();

  var payload = JSON.parse(JSON.stringify(opts));
  /* the page is static, so the watch's platform has to travel with the
   * settings: it decides which date formats are worth offering */
  payload._maxDate = maxDateFormat();

  /* the '#' must stay outside the encoded payload, otherwise the settings
   * JSON becomes part of the document instead of the fragment */
  Pebble.openURL(CONFIG_URL + '#' + encodeURIComponent(JSON.stringify(payload)));
});

Pebble.addEventListener('webviewclosed', function (e) {
  if (!e.response) return;
  var opts;
  try { opts = JSON.parse(decodeURIComponent(e.response)); } catch (err) { return; }
  saveOpts(opts);
  sendOpts(opts);
});
